files['ppt/slideMasters/_rels/slideMaster1.xml.rels']=rel([(1,'slideLayout','../slideLayouts/slideLayout1.xml'),(2,'theme','../theme/theme1.xml')])
files['ppt/slideLayouts/slideLayout1.xml']=f'<p:sldLayout xmlns:p="{P}" xmlns:a="{A}" type="blank" preserve="1"><p:cSld name="Blank"><p:spTree>{grp}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>'
files['ppt/slideLayouts/_rels/slideLayout1.xml.rels']=rel([(1,'slideMaster','../slideMasters/slideMaster1.xml')])
colors=['111827','FFFFFF','182338','E9EEF5','55D6BE','EF5670','6BA3FF','E9C46A','9C89B8','E07A5F','6BA3FF','9C89B8']
