files['ppt/theme/theme1.xml']=f'<a:theme xmlns:a="{A}" name="Konnco"><a:themeElements><a:clrScheme name="Konnco">'+''.join(f'<a:{n}><a:srgbClr val="{c}"/></a:{n}>' for n,c in zip(names,colors))+'</a:clrScheme><a:fontScheme name="Aptos"><a:majorFont><a:latin typeface="Aptos"/><a:ea typeface=""/><a:cs typeface=""/></a:majorFont><a:minorFont><a:latin typeface="Aptos"/><a:ea typeface=""/><a:cs typeface=""/></a:minorFont></a:fontScheme><a:fmtScheme name="Simple"><a:fillStyleLst/><a:lnStyleLst/><a:effectStyleLst/><a:bgFillStyleLst/></a:fmtScheme></a:themeElements></a:theme>'
for i,(title,body,notes) in enumerate(slides,1):
 cover=i==1; code=i in [6,8,9,10,14]; size=20 if code else 24
 shapes=box(2,54,90 if cover else 45,850,140 if cover else 85,title,42 if cover else 32,'55D6BE',True)
